  "description": "Dump 01_入院病史与查体.pdf text",
  "command": "python3 -c "
import fitz

def dump_pdf(path):
    print(f'=== {path} ===')
    doc = fitz.open(path)
    for i, page in enumerate(doc):
        print(f'--- Page {i+1} ---')
        print(page.get_text())

dump_pdf('/app/data/input_files/01_入院病史与查体.pdf')
""
